cases.setup:
Create ForceModel FM;
FM.PrimaryBodies = {Earth};
FM.PointMasses = {Luna};
FM.GravityField.Earth.PotentialFile = 'JGM2.cof';
FM.GravityField.Earth.Degree = 4;
FM.GravityField.Earth.Order = 2;
FM.SRP = On;
FM.SRP.Flux = 1400;
FM.SRP.Nominal_Sun = 150000000;
FM.Drag.AtmosphereModel = NRLMSISE00;
FM.Drag.F107 = 160;
FM.Drag.F107A = 155;
FM.Drag.MagneticIndex = 4;
FM.RelativisticCorrection = On;
Create Propagator Prop;
Prop.FM = FM;
Prop.InitialStepSize = 120;

cases.spacecraft_setup:
Create Spacecraft Sat;
Sat.NAIFId = -101101;
Sat.NAIFIdReferenceFrame = -910101;
Sat.CoordinateSystem = EarthMJ2000Eq;
Sat.DateFormat = A1ModJulian;
Sat.Epoch = '21545';
Sat.DisplayStateType = Cartesian;
Sat.X = 7000;
Sat.Y = 0;
Sat.Z = 0;
Sat.VX = 0;
Sat.VY = 7.5;
Sat.VZ = 1;

